import {INTENTIONS} from './stage.mjs?v=0.6.2';
import {rand,clamp,round,log,GENRES} from './engine.mjs?v=0.6.2';
const live=['applied','booked','assembling','playing'];
export const pendingBooking=(s,id)=>s.bookings.find(b=>b.groupId===id&&live.includes(b.status));
export function morale(g,time){return clamp(60+(g.moraleEffects||[]).reduce((n,e)=>n+e.amount*Math.max(0,1-(time-e.time)/(e.until-e.time)),0));}
export function moraleEffect(s,g,amount,reason,duration=2880){g.moraleEffects||=[];g.moraleEffects.push({id:`m-${g.id}-${s.eventId+1}`,amount,time:s.time,until:s.time+duration,reason});g.moraleEffects=g.moraleEffects.filter(e=>e.until>s.time).slice(-8);}
export function makeEvent(s,time){const n=s.nextEventOrdinal++,big=n%4===0;const genres=[['Indie','Folk','Pop'],['Ska','Jazz','Électro'],['Punk','Métal','Indie'],['Pop','Indie','Ska','Folk']][(n-1)%4];return {id:`event-${n}`,ordinal:n,name:(big?'★ Fête des Érables': ['La cour des voisins','Les Amplis au parc','Une nuit au Canal'][(n-1)%3])+` · ${n}`,venue:['g1','park','g2','g1'][(n-1)%4],day:Math.floor(time/1440)+1,time,styles:genres,crowd:big?24:12,final:big,status:'open',bookingId:null,opened:s.time,selectionAt:time-2880,selected:false,slots:Array.from({length:big?3:2},(_,i)=>({id:`event-${n}-slot-${i}`,role:i===(big?2:1)?'Tête d’affiche':'Première partie',duration:i===(big?2:1)?20:10,bookingId:null})),organizer:{discovery:n%2===0,exigence:big?60:30}};}
export function eventById(s,id){return s.season.opportunities.find(o=>o.id===id)||s.eventArchive?.find(o=>o.id===id);}
export function initializeCalendar(s){s.calendarVersion=1;s.eventArchive=[];s.nextEventOrdinal=1;s.season={started:s.time,ended:false,opportunities:Array.from({length:4},(_,i)=>makeEvent(s,s.time+4320+i*2880))};}
export function upgradeCalendar(s){if(s.calendarVersion===1)return;const old=s.season?.opportunities||[];s.eventArchive||=[];s.nextEventOrdinal=1;for(const o of old){const previousId=o.id;o.id=`legacy-${s.season.started}-${previousId}`;for(const b of s.bookings)if(b.opportunityId===previousId)b.opportunityId=o.id;for(const r of s.showHistory)if(r.opportunityId===previousId)r.opportunityId=r.time>=s.season.started?o.id:`legacy-history-${r.time}-${previousId}`;if(s.performance?.opportunityId===previousId){s.performance.opportunityId=o.id;s.performance.sourceOpportunity.id=o.id;}o.ordinal=s.nextEventOrdinal++;o.selected=true;o.slots=[];const bookings=s.bookings.filter(b=>b.opportunityId===o.id);for(const [i,b] of bookings.entries()){b.setlist||=[b.songId];b.slotId=`${o.id}-${s.season.started}-slot-${i}`;o.slots.push({id:b.slotId,role:'Prestation héritée',duration:Math.max(10,b.setlist.length*4),bookingId:b.id});}while(o.slots.length<2)o.slots.push({id:`${o.id}-${s.season.started}-slot-${o.slots.length}`,role:'Première partie',duration:10,bookingId:null});o.selectionAt=o.time-2880;o.organizer={discovery:false,exigence:o.final?60:30};}s.calendarVersion=1;s.season.ended=false;rollCalendar(s);}
export function rollCalendar(s){const future=s.season.opportunities.filter(o=>o.time>s.time),current=s.season.opportunities.filter(o=>o.time<=s.time);for(const o of current){if(!s.eventArchive.some(x=>x.id===o.id))s.eventArchive.push(o);}s.season.opportunities=future;while(s.season.opportunities.length<4){const last=s.season.opportunities.at(-1);s.season.opportunities.push(makeEvent(s,Math.max(s.time+4320,last?last.time+2880:0)));}s.season.ended=false;}
export function assess(s,g,o){const people=g.members.map(id=>s.people.find(p=>p.id===id)).filter(Boolean);const energy=people.reduce((n,p)=>n+p.needs.energy,0)/Math.max(1,people.length),skill=people.reduce((n,p)=>n+p.skills[p.instrument],0)/Math.max(1,people.length);const mastery=g.repertoire.reduce((n,r)=>n+r.mastery,0)/Math.max(1,g.repertoire.length);const fit=o.styles.includes(g.genre)?22:0;const score=skill*.25+g.development*.23+mastery*.18+g.reputation*.14+energy*.1+fit;return {score,energy,skill,mastery,risk:score>o.organizer.exigence+8?'Accessible':score>o.organizer.exigence-12?'Ambitieux':'Très risqué',reasons:[fit?'Public compatible':`Public peu familier du ${g.genre}`,`Coordination ${round(g.development)} · énergie ${round(energy)}`]};}
export function candidateWeight(s,g,o){const a=assess(s,g,o),other=o.slots.map(slot=>s.bookings.find(b=>b.id===slot.bookingId)).filter(Boolean).map(b=>s.groups.find(g=>g.id===b.groupId)?.genre);return Math.max(1,4+a.score*.6+g.reputation*.18+(o.organizer.discovery?(100-g.reputation)*.12:0)+(other.includes(g.genre)?-12:8));}
export function bookShow(s,cmd,acceptance,availability){const g=s.groups.find(g=>g.id===cmd.groupId&&g.archivedAt===null),o=eventById(s,cmd.opportunityId),host=s.people.find(p=>p.id===cmd.actorId);if(!g||!host||!g.members.includes(host.id)||!o||o.time<=s.time||!INTENTIONS[cmd.intention||'tight'])return {ok:false,message:'Choisis un band actif et une date à venir.'};if(pendingBooking(s,g.id))return {ok:false,message:'Ce band a déjà un engagement ou une candidature. Annule-le pour changer de date.'};if(o.final&&o.selected)return {ok:false,message:'Les candidatures de ce gros show sont fermées.'};const slot=cmd.slotId?o.slots.find(x=>x.id===cmd.slotId&&!x.bookingId):o.slots.find(x=>!x.bookingId);if(!slot)return {ok:false,message:'Tous les créneaux sont pris.'};const setlist=(cmd.setlist||[cmd.songId??null]).map(x=>x===null?null:Number(x));if(!setlist.length||setlist.length>5||setlist.some(id=>id!==null&&!g.repertoire.some(r=>r.songId===id)))return {ok:false,message:'Choisis des morceaux du répertoire ou une improvisation.'};if(setlist.length*4>slot.duration)return {ok:false,message:`La setlist dépasse les ${slot.duration} minutes disponibles.`};const members=[],refused=[];for(const id of [...new Set(cmd.members||g.members)]){const p=s.people.find(p=>p.id===id);if(!p||!g.members.includes(id))continue;const free=availability(s,p,o.time,slot.duration,o.id,slot.id);if(!free.available){refused.push({id,reason:free.reason});log(s,'conflict',`${p.name} décline un engagement incompatible : ${free.reason}.`,[p.id,host.id],{groupId:g.id});if(id!==host.id){const relation=s.rels[`${p.id}>${host.id}`];if(relation)relation.tension=clamp(relation.tension+4);}continue;}if(id!==host.id&&rand(s)>=acceptance(s,host,p,g)){refused.push({id,reason:'Préfère poursuivre ses projets'});continue;}members.push(id);}if(!members.includes(host.id)||members.length<2)return {ok:false,message:'Deux confirmations, dont celle de l’organisateur, sont nécessaires.',refused};const b={id:`b${s.nextBookingId++}`,groupId:g.id,opportunityId:o.id,slotId:slot.id,role:slot.role,duration:slot.duration,setlist,songId:setlist[0],time:o.time,created:s.time,intention:cmd.intention||'tight',members,refused,status:o.final?'applied':'booked',performanceId:null};s.bookings.push(b);if(!o.final){slot.bookingId=b.id;o.status='booked';o.bookingId=b.id;}log(s,'booking',`${g.name} ${o.final?'pose sa candidature pour':'réserve'} ${o.name}.`,members,{bookingId:b.id,groupId:g.id,explanation:assess(s,g,o).reasons.join(' · ')});return {ok:true,message:o.final?'Candidature déposée. Résultat deux jours avant le show.':'Créneau réservé. Prépare la setlist et répète.',bookingId:b.id,refused};}
export function selectBands(s,o){if(o.selected)return;o.selected=true;let pool=s.bookings.filter(b=>b.opportunityId===o.id&&b.status==='applied');for(const slot of [...o.slots].reverse().filter(x=>!x.bookingId)){const eligible=pool.filter(b=>b.setlist.length*4<=slot.duration&&b.members.every(id=>{const conflict=s.bookings.some(other=>other!==b&&other.status==='booked'&&other.members.includes(id)&&Math.abs(other.time-b.time)<180&&other.opportunityId!==o.id);return !conflict;}));if(!eligible.length)continue;const weights=eligible.map(b=>candidateWeight(s,s.groups.find(g=>g.id===b.groupId),o));let roll=rand(s)*weights.reduce((a,b)=>a+b,0),i=weights.findIndex(w=>(roll-=w)<0);if(i<0)i=eligible.length-1;const b=eligible[i];pool=pool.filter(x=>x!==b);Object.assign(b,{status:'booked',slotId:slot.id,role:slot.role,duration:slot.duration});slot.bookingId=b.id;log(s,'booking',`${s.groups.find(g=>g.id===b.groupId).name} est retenu pour ${slot.role.toLowerCase()} à ${o.name}.`,b.members,{bookingId:b.id,explanation:'Adéquation, préparation, réputation, découverte et complémentarité; tirage pondéré enregistré.'});}for(const b of pool){b.status='rejected';b.resultTime=s.time;const g=s.groups.find(g=>g.id===b.groupId);moraleEffect(s,g,-8,'Candidature non retenue');g.nextBookingAttempt=s.time+360;log(s,'booking',`${g.name} n’est pas retenu. Moral temporaire −8; réputation conservée.`,b.members,{bookingId:b.id,groupId:g.id});}o.status=o.slots.some(x=>x.bookingId)?'booked':'open';}
export function calendarMinute(s,acceptance,availability){rollCalendar(s);for(const o of s.season.opportunities)if(o.final&&!o.selected&&s.time>=o.selectionAt)selectBands(s,o);if(s.time%180)return;const bands=s.groups.filter(g=>g.archivedAt===null&&g.members.length>=2);for(let i=bands.length-1;i>0;i--){const j=Math.floor(rand(s)*(i+1));[bands[i],bands[j]]=[bands[j],bands[i]];}for(const g of bands){g.moraleEffects=(g.moraleEffects||[]).filter(e=>e.until>s.time);if(pendingBooking(s,g.id)||(g.nextBookingAttempt||0)>s.time)continue;g.nextBookingAttempt=s.time+360;const candidates=s.season.opportunities.filter(o=>(!o.final||!o.selected)&&o.slots.some(x=>!x.bookingId)&&o.time-s.time>=240).map(o=>({o,...assess(s,g,o)}));const people=g.members.map(id=>s.people.find(p=>p.id===id)).filter(Boolean),ambition=people.reduce((n,p)=>n+p.personality.ambition,0)/people.length,discipline=people.reduce((n,p)=>n+p.personality.discipline,0)/people.length;const ranked=candidates.map(c=>({...c,value:c.score-c.o.organizer.exigence*.55+ambition*.14+morale(g,s.time)*.15-(c.o.final&&c.risk==='Très risqué'?discipline*.35:0)})).sort((a,b)=>b.value-a.value);const best=ranked[0];if(!best||best.energy<35||best.value<28||rand(s)>.18+ambition*.004)continue;const songs=[...g.repertoire].sort((a,b)=>b.mastery-a.mastery).slice(0,2).map(r=>r.songId);bookShow(s,{actorId:people[0].id,groupId:g.id,opportunityId:best.o.id,intention:'tight',setlist:songs.length?songs:[null],members:g.members},acceptance,availability);}}
export function validateCalendar(s){const ids=new Set();for(const o of [...s.season.opportunities,...s.eventArchive]){if(ids.has(o.id)||!Number.isInteger(o.time)||!Array.isArray(o.slots)||!o.slots.length)throw Error('Calendrier V6 invalide.');ids.add(o.id);}if(s.season.opportunities.length!==4||!Number.isInteger(s.nextEventOrdinal))throw Error('Quatre dates futures requises.');for(const g of s.groups)if((g.moraleEffects||[]).some(e=>!Number.isFinite(e.amount)||!Number.isFinite(e.until)||e.until<=e.time))throw Error('Moral invalide.');}
export function modifyBooking(s,cmd,acceptance,availability){const old=s.bookings.find(b=>b.id===cmd.bookingId&&['applied','booked'].includes(b.status));if(!old)return {ok:false,message:'La formation se déplace déjà. Annule cet engagement pour changer.'};if(!old.members.includes(cmd.actorId))return {ok:false,message:'Choisis un membre confirmé.'};const clone=JSON.parse(JSON.stringify(s)),previous=clone.bookings.find(b=>b.id===old.id),o=eventById(clone,old.opportunityId),slot=o.slots.find(x=>x.id===old.slotId);previous.status='cancelled';const big=o.final,selected=o.selected;if(slot?.bookingId===old.id)slot.bookingId=null;o.final=false;o.selected=false;const r=bookShow(clone,{...cmd,opportunityId:old.opportunityId,groupId:old.groupId,slotId:old.slotId},acceptance,availability);if(!r.ok)return r;o.final=big;o.selected=selected;const fresh=clone.bookings.find(b=>b.id===r.bookingId);fresh.status=old.status;if(old.status==='applied'){const assigned=o.slots.find(x=>x.bookingId===fresh.id);if(assigned)assigned.bookingId=null;}Object.assign(s,clone);log(s,'booking','La préparation a été modifiée et les confirmations revalidées.',fresh.members,{bookingId:fresh.id});return {...r,message:'Préparation modifiée. L’engagement précédent est remplacé.'};}
